/// VkDebugUtilsMessageSeverityFlagsEXT
pub const DebugUtilsMessageSeverityFlagsEXT = packed struct(u32) {
    verbose: bool = false,
    _reserved_1: u3 = 0,
    info: bool = false,
    _reserved_5: u3 = 0,
    warning: bool = false,
    _reserved_9: u3 = 0,
    @"error": bool = false,
    _reserved: u19 = 0,

    /// Does this set have every bit of `wanted` set?
    pub fn contains(self: DebugUtilsMessageSeverityFlagsEXT, wanted: DebugUtilsMessageSeverityFlagsEXT) bool {
        const have: u32 = @bitCast(self);
        const need: u32 = @bitCast(wanted);
        return have & need == need;
    }
};

